from dataclasses import dataclass

@dataclass
class Task:
    title: str
    done: bool = False

    def complete(self) -> None:
        self.done = True

def summarize(tasks: list[Task]) -> dict[str, int]:
    return {
        "total": len(tasks),
        "done": sum(task.done for task in tasks),
    }

tasks = [Task("Learn"), Task("Build", True)]
print(summarize(tasks))

